/* ============================================================================
   Add the remaining 140 FC recipes (Excel Sep2026) as NEW QC/RD menus
   (the other 44 were already saved with import-bom-excel-sep2026-44.sql)

   *** DRY RUN BY DEFAULT: first run shows S1/S2/S3/S4 and saves NOTHING (ROLLBACK). ***
   Check the results, then change  DECLARE @apply BIT = 0  (just below) to 1 and run again.

   - New menu code = 'FC' + Excel code (e.g. FC6087). NOT the plain 4-digit code: the usage
     page matches POS sales by code against qcrd_bom.menu_code, so a plain number could
     collide with a real POS menu and deduct stock wrongly. 'FC...' can never match POS.
   - A recipe is SKIPPED when QC/RD already has a menu with a similar name (spaces, brackets,
     punctuation, Thai tone marks ignored) or the code exists. S2 lists them - map by hand.
   - Item names from dbo.stock_item, else from Excel. Price from stock_item (none -> cost 0).
   - Created codes are logged in dbo.qcrd_menu_created_excel_sep2026 (undo block at the end).
   Pure ASCII (Thai stored as hex). Open in Notepad, Ctrl+A, Ctrl+C, paste in New Query, Execute.
   ============================================================================ */
USE InventoryNarai;
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @apply BIT = 0;   -- <<<<<< 0 = dry run (nothing saved), 1 = save for real

IF OBJECT_ID('tempdb..#m') IS NOT NULL DROP TABLE #m;
CREATE TABLE #m (menu_code NVARCHAR(50), yield_qty DECIMAL(18,4), menu_name NVARCHAR(255),
                 nkey NVARCHAR(255) NULL, status VARCHAR(30) NULL,
                 similar_code NVARCHAR(50) NULL, similar_name NVARCHAR(255) NULL);
