/* ---------- similar-name check against every QC/RD menu ---------- */
IF OBJECT_ID('tempdb..#q') IS NOT NULL DROP TABLE #q;
SELECT menu_code, menu_name, CAST(menu_name AS NVARCHAR(255)) AS nkey INTO #q FROM dbo.qcrd_menu;
UPDATE #m SET nkey = menu_name;
UPDATE #q SET nkey = REPLACE(nkey, ' ', '');
UPDATE #q SET nkey = REPLACE(nkey, NCHAR(160), '');
UPDATE #q SET nkey = REPLACE(nkey, NCHAR(9), '');
UPDATE #q SET nkey = REPLACE(nkey, '(', '');
