UPDATE #q SET nkey = REPLACE(nkey COLLATE Latin1_General_BIN2, NCHAR(3655), '');
UPDATE #q SET nkey = REPLACE(nkey COLLATE Latin1_General_BIN2, NCHAR(3656), '');
