UPDATE m SET status = 'SKIP_CODE_EXISTS'
FROM #m m WHERE EXISTS (SELECT 1 FROM dbo.qcrd_menu q WHERE q.menu_code = m.menu_code);
UPDATE m SET status = 'SKIP_SIMILAR_NAME', similar_code = s.menu_code, similar_name = s.menu_name
FROM #m m
CROSS APPLY (SELECT TOP 1 q.menu_code, q.menu_name FROM #q q
             WHERE q.nkey COLLATE Latin1_General_BIN2 = m.nkey COLLATE Latin1_General_BIN2
             ORDER BY q.menu_code) s
WHERE m.status IS NULL;
UPDATE #m SET status = 'CREATE' WHERE status IS NULL;

PRINT '===== S1) result per recipe =====';
SELECT status, COUNT(*) AS recipes FROM #m GROUP BY status ORDER BY status;
PRINT '===== S2) skipped: QC/RD already has a similar menu (map by hand) =====';
SELECT menu_code, menu_name, status, similar_code, similar_name FROM #m
WHERE status <> 'CREATE' ORDER BY menu_code;

/* ---------- write (inside a transaction; rolled back when @apply = 0) ---------- */
BEGIN TRAN;

IF OBJECT_ID('dbo.qcrd_menu_created_excel_sep2026', 'U') IS NULL
    CREATE TABLE dbo.qcrd_menu_created_excel_sep2026 (
        menu_code NVARCHAR(50) NOT NULL, created_at DATETIME2(0) NOT NULL);

DECLARE @sort INT = (SELECT ISNULL(MAX(sort_order), 0) FROM dbo.qcrd_menu);
SELECT menu_code, LOWER(menu_code), menu_name, NULL, yield_qty,
       @sort + ROW_NUMBER() OVER (ORDER BY menu_code)
FROM #m WHERE status = 'CREATE';

SELECT menu_code, SYSDATETIME() FROM #m WHERE status = 'CREATE';

     unit_cost, line_cost, src_code, src_name, src_factor, src_base, tag, no_deduct)
SELECT n.menu_code, m.menu_name, n.seq, n.item_code, k.item_key,
       COALESCE(si.item_name, xi.item_name, n.item_code), n.qty, CASE WHEN n.converter = 0 THEN 1000 ELSE n.converter END,
       NULLIF(si.price, 0),
       CASE WHEN si.price > 0 THEN si.price / CASE WHEN n.converter = 0 THEN 1000 ELSE n.converter END END,
       CASE WHEN si.price > 0 THEN n.qty * si.price / CASE WHEN n.converter = 0 THEN 1000 ELSE n.converter END END,
       NULL, NULL, NULL, NULL, NULL, 0
FROM #n n
JOIN #m m ON m.menu_code = n.menu_code AND m.status = 'CREATE'
CROSS APPLY (SELECT LOWER(ISNULL(NULLIF(SUBSTRING(n.item_code,
             PATINDEX('%[^0]%', n.item_code + '.'), 50), ''), '0')) AS item_key) k
LEFT JOIN #i xi ON xi.item_code = n.item_code
OUTER APPLY (SELECT TOP 1 s.item_name, s.price FROM dbo.stock_item s
             WHERE LOWER(s.item_key) = k.item_key) si;

UPDATE qm SET cost = (SELECT ROUND(SUM(ISNULL(b.line_cost, 0)), 4) FROM dbo.qcrd_bom b
                      WHERE b.menu_code = qm.menu_code),
       updated_at = SYSDATETIME()
FROM dbo.qcrd_menu qm JOIN #m m ON m.menu_code = qm.menu_code AND m.status = 'CREATE';

PRINT '===== S3) lines written (expected = saved) =====';
SELECT (SELECT COUNT(*) FROM #m WHERE status = 'CREATE') AS expected_menus,
       COUNT(DISTINCT b.menu_code) AS menus_written,
       (SELECT COUNT(*) FROM #n n JOIN #m m ON m.menu_code = n.menu_code AND m.status = 'CREATE')
           AS expected_lines,
       COUNT(*) AS lines_written
FROM dbo.qcrd_bom b JOIN #m m ON m.menu_code = b.menu_code AND m.status = 'CREATE';

PRINT '===== S4) items with no price in stock_item (cost 0 on those lines) =====';
SELECT DISTINCT n.item_code, COALESCE(xi.item_name, n.item_code) AS item_name
FROM #n n JOIN #m m ON m.menu_code = n.menu_code AND m.status = 'CREATE'
LEFT JOIN #i xi ON xi.item_code = n.item_code
WHERE NOT EXISTS (SELECT 1 FROM dbo.stock_item s
                  WHERE LOWER(s.item_key) = LOWER(ISNULL(NULLIF(SUBSTRING(n.item_code,
                        PATINDEX('%[^0]%', n.item_code + '.'), 50), ''), '0')) AND s.price > 0)
ORDER BY n.item_code;

IF @apply = 1
BEGIN
    COMMIT;
    PRINT '*** SAVED (COMMIT). Created codes: dbo.qcrd_menu_created_excel_sep2026';
END
ELSE
BEGIN
    ROLLBACK;
    PRINT '*** DRY RUN ONLY - nothing saved (ROLLBACK). Set @apply = 1 and run again to save.';
END

